mapper.select:
select tpd.INT_AMT intAmt, tpd.FINPROD_TYPE feeType, tpd.CCY ccy, tpd.TRADE_STATUS tradeStatus, bdad.BOK_DETAIL_ID bokDetailId, tpd.finprod_id finprodId from TRD_PRODUCT_DEAL tpd inner join TRD_PRODUCT_DEAL_ADD tpde on tpd.TRADE_ID = tpde.TRADE_ID inner join BOK_DEAL_ACCOUNTING bda on bda.BUSI_NO = tpd.TRADE_ID
and BUSI_TABLE = #{busiTable,jdbcType=VARCHAR} inner join BOK_DEAL_ACCOUNTING_DETAIL bdad on tpd.TRADE_ID = bdad.BUSI_NO and bdad.BUSI_TABLE = #{busiTable,jdbcType=VARCHAR} and bdad.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR} where 1=1
and bda.BOOK_DATE = #{happenDate,jdbcType=DATE}
and bda.BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
and tpd.PS = #{ps,jdbcType=VARCHAR}
